// GetModuleControllersCmd represents the command 'tptctl get module-controllers'
var GetModuleControllersCmd = &cobra.Command{
	Aliases: []string{"module-controller"},
	Example: "  # get all module controllers\n  tptctl get module-controllers\n\n  # get a specific module controller\n  tptctl get module-controller --name some-module-controller",
	Long:    "Get module controllers from the system. Use --name to get a specific module controller.",
	PreRun:  CommandPreRunFunc,
	Run: func(cmd *cobra.Command, args []string) {
		apiClient, _, apiEndpoint, requestedControlPlane := GetClientContext(cmd)

		// flag validation
		if err := cli.ValidateConfigNameFlags(
			moduleConfigPath,
			moduleName,
			"module controller",
		); err != nil {
			cli.Error("flag validation failed", err)
			os.Exit(1)
		}

		switch moduleVersion {
		case "v0":
			// load values
			moduleControllerConfig := config_v0.ModuleControllerConfig{}
			if moduleConfigPath != "" {
				configContent, err := os.ReadFile(moduleConfigPath)
				if err != nil {
					cli.Error("failed to read config file", err)
					os.Exit(1)
				}
				if err := yaml.UnmarshalStrict(configContent, &moduleControllerConfig); err != nil {
					cli.Error("failed to unmarshal config file yaml content", err)
					os.Exit(1)
				}
			} else if moduleName != "" {
				moduleControllerConfig = config_v0.ModuleControllerConfig{
					ModuleController: config_v0.ModuleControllerValues{
						Name: &moduleName,
					},
				}
			}

			// get module controllers
			moduleControllers, err := moduleControllerConfig.Get(apiClient, apiEndpoint)
			if err != nil {
				cli.Error("failed to retrieve module controllers", err)
				os.Exit(1)
			}

			// check if module controller exists
			if len(*moduleControllers) == 0 {
				cli.Info(fmt.Sprintf(
					"no module controllers found that are currently managed by %s threeport control plane",
					requestedControlPlane,
				))
				os.Exit(0)
			}

			// write the output
			switch moduleOutput {
			case "tabular":
				if err := outputGetv0ModuleControllersCmd(moduleControllers); err != nil {
					cli.Error("failed to produce output", err)
					os.Exit(1)
				}
			case "yaml":
				if err := cli.YamlObjectOutput(*moduleControllers); err != nil {
					cli.Error("failed to produce YAML output", err)
					os.Exit(1)
				}
			case "json":
				if err := cli.JsonObjectOutput(*moduleControllers); err != nil {
					cli.Error("failed to produce JSON output", err)
					os.Exit(1)
				}
			default:
				cli.Error("", fmt.Errorf("unrecognized output format: %s", moduleOutput))
				os.Exit(1)
			}
		default:
			cli.Error("", errors.New("unrecognized object version"))
			os.Exit(1)
		}
	},
	Short:        "Get module controllers from the system",
	SilenceUsage: true,
	Use:          "module-controllers",
}

func init() {
	GetCmd.AddCommand(GetModuleControllersCmd)

	GetModuleControllersCmd.Flags().StringVarP(
		&moduleName,
		"name", "n", "", "Name of module controller.",
	)
	GetModuleControllersCmd.Flags().StringVarP(
		&moduleConfigPath,
		"config", "c", "", "Path to file with module controller config.",
	)
	GetModuleControllersCmd.Flags().StringVarP(
		&moduleVersion,
		"version", "v", "v0", "Version of module controller objects to retrieve. One of: [v0]",
	)
	GetModuleControllersCmd.Flags().StringVarP(
		&moduleOutput,
		"output", "o", "tabular", "Output format for module controller objects. One of: [tabular, yaml, json]",
	)
	GetModuleControllersCmd.Flags().StringVarP(
		&cliArgs.ControlPlaneName,
		"control-plane-name", "i", "", "Optional. Name of control plane. Will default to current control plane if not provided.",
	)
}

